import {downloadPNG} from './image-download.js?v=cad18';
import * as THREE from 'three';
import {TransformControls} from '../vendor/TransformControls.js';
import {smartSnap,snapElevation,normalizeAngle,clampGroupTranslation,validPosition,canPlace,alignModules,constructionWarnings,openingWarnings,resizeCoupled} from './assembly.mjs?v=cad18';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function installAssembly({getProject,current,commit,scene,toast,renderInspector,selectPart}){const ids=new Set();let active=false,additive=false,guard=false,gizmoMode='translate',dragStart=null;const settings={snap:true,block:false,gap:2,maxShelf:900,maxDoor:700,coupled:true};const panel=document.createElement('details');panel.className='pro-toolbox';panel.id='assembly-panel';panel.innerHTML=`<summary>Точная сборка · PRO</summary><div><button data-gizmo="translate">Стрелки XYZ</button><button data-gizmo="rotate">Кольцо поворота</button><button id="gizmo-off">Убрать</button></div><label><input id="smart-snap" type="checkbox" checked> Привязка к мебели и стенам</label><label>Зазор, мм <input id="join-gap" type="number" min="0" max="100" value="2"></label><label><input id="block-overlap" type="checkbox"> Запретить пересечения при переносе</label><label><input id="coupled-size" type="checkbox" checked> Масштабировать изменённые детали с модулем</label><div class="pro-actions"><button id="group-selected">Группировать</button><button id="ungroup-selected">Разгруппировать</button><button data-align-pro="front">По фасаду</button><button data-align-pro="top">По верху</button><button data-align-pro="left">По левому краю</button></div><p id="selection-info">Shift/Ctrl + щелчок: несколько модулей</p><div id="group-picker"></div><button id="explode-pro-open">Разобрать и настроить детали ↗</button><h4>Дерево конструкции</h4><div id="part-tree" class="pro-tree"></div><h4>Проверки конструкции</h4><label>Предельный пролёт полки, мм <input id="shelf-limit" type="number" min="300" max="2000" value="900"></label><label>Предельная ширина фасада, мм <input id="door-limit" type="number" min="300" max="1500" value="700"></label><button id="construction-check">Проверить открывание и размеры</button><div id="construction-result"></div><h4>Материал</h4><label>Покрытие фасада<select id="finish-class"><option value="matte">Матовая эмаль</option><option value="lacquer">Лак</option><option value="plastic">Пластик</option><option value="veneer">Шпон</option><option value="metal">Металл</option></select></label><label>Кромка корпуса<input id="edge-color" type="color" value="#c5ac84"></label><label>Зазор фасадов, мм<input id="front-gap" type="number" min="1" max="12" step="1" value="4"></label><button id="quality-render">Качественный снимок ↗</button>`;$('#module-pane').prepend(panel);const hud=document.createElement('div');hud.className='pro-hud';hud.hidden=true;scene.host.parentElement.append(hud);
const gizmo=new TransformControls(scene.camera,scene.renderer.domElement);gizmo.setSize(.8);gizmo.setTranslationSnap(.01);gizmo.setRotationSnap(Math.PI/180);const helper=gizmo.getHelper();scene.scene.add(helper);gizmo.enabled=false;gizmo.addEventListener('change',()=>{scene.dirty=true;});
function attach(){if(gizmo.dragging)return;gizmo.detach();gizmo.userDataTarget=null;if(!active||scene.exploder.active||!current()||current().locked)return;let target=scene.groups.get(current().id);if(scene.detailMode&&scene.partId)target?.traverse(o=>{if(o.isGroup&&o.userData.partId===scene.partId)gizmo.userDataTarget=o;});if(scene.detailMode&&scene.partId&&gizmo.userDataTarget)target=gizmo.userDataTarget;gizmo.camera=scene.camera;gizmo.setMode(gizmoMode);gizmo.showX=gizmoMode==='translate';gizmo.showY=true;gizmo.showZ=gizmoMode==='translate';if(target)gizmo.attach(target);gizmo.enabled=true;}
gizmo.addEventListener('dragging-changed',e=>{scene.controls.enabled=!e.value;scene.gizmoDragging=e.value;if(e.value){const m=current(),o=gizmo.object;dragStart={id:m.id,partId:scene.detailMode?scene.partId:null,pos:o.position.clone(),rotation:o.rotation.y,initial:structuredClone(m),all:structuredClone(getProject().modules)};}else if(dragStart){const m=current(),o=gizmo.object,s=dragStart;dragStart=null;if(!m||!o)return;const delta=o.position.clone().sub(s.pos);if(s.partId){m.details||={};m.details[s.partId]||={};const old=s.initial.details?.[s.partId]||{};for(const k of ['x','y','z'])m.details[s.partId][k]=Math.max(-3000,Math.min(3000,Math.round((old[k]||0)+delta[k]*1000)));m.details[s.partId].rotation=normalizeAngle((old.rotation||0)+(o.rotation.y-s.rotation)*180/Math.PI);}else{const rotation=(o.rotation.y-s.rotation)*180/Math.PI;for(const item of getProject().modules.filter(x=>ids.has(x.id)&&!x.locked)){const old=s.all.find(x=>x.id===item.id);const angle=rotation*Math.PI/180,ox=old.x-s.initial.x,oz=old.z-s.initial.z;item.x=Math.round(s.initial.x+ox*Math.cos(angle)+oz*Math.sin(angle)+delta.x*1000);item.y=Math.max(0,Math.min(2800,Math.max(0,getProject().room.height-item.height),Math.round(old.y+delta.y*1000)));item.z=Math.round(s.initial.z-ox*Math.sin(angle)+oz*Math.cos(angle)+delta.z*1000);item.rotation=Math.round(old.rotation+rotation)%360;}if(settings.snap&&ids.size===1){const snapped=smartSnap(m,getProject(),{gap:settings.gap});m.x=snapped.module.x;m.z=snapped.module.z;snapElevation(m,getProject());}if(getProject().modules.some(item=>!validPosition(item))||(settings.block&&!canPlace(getProject(),[...ids]))){getProject().modules=s.all;toast('Пересечение или предел координат: перемещение отменено');}}commit({rebuild:true});hud.hidden=true;attach();}});
gizmo.addEventListener('objectChange',()=>{const o=gizmo.object;if(!o)return;hud.hidden=false;hud.textContent=`X ${Math.round(o.position.x*1000)} · Y ${Math.round(o.position.y*1000)} · Z ${Math.round(o.position.z*1000)} мм · ${Math.round(o.rotation.y*180/Math.PI)}°`;scene.dirty=true;});
window.addEventListener('pointerdown',e=>{additive=e.shiftKey||e.ctrlKey||e.metaKey;},true);
const onSelect=scene.onSelect;scene.onSelect=id=>{if(gizmo.dragging)return;const m=getProject().modules.find(m=>m.id===id);if(additive&&id){ids.has(id)?ids.delete(id):ids.add(id);}else{ids.clear();if(m?.groupId)getProject().modules.filter(o=>o.groupId===m.groupId).forEach(o=>ids.add(o.id));else if(id)ids.add(id);}onSelect(id);render();};
const oldSelect=scene.select.bind(scene);scene.select=id=>{oldSelect(id);if(!guard){guard=true;for(const other of ids)if(other!==id){const g=scene.groups.get(other);if(g?.visible){g.updateWorldMatrix(true,true);const box=new THREE.Box3Helper(new THREE.Box3().setFromObject(g),0x6f9145);box.material.depthTest=false;scene.overlay.add(box);}}guard=false;}attach();};
const oldMove=scene.onMove;scene.onMove=(id,x,z,step)=>{const p=getProject(),m=p.modules.find(m=>m.id===id),before=structuredClone(p.modules);if(!ids.has(id)){ids.clear();ids.add(id);}const old={x:m.x,z:m.z};let candidate={...m,x,z};const result=settings.snap?smartSnap(candidate,p,{gap:settings.gap,grid:step||10,exclude:[...ids]}):{module:candidate,guides:[]};const {dx,dz}=clampGroupTranslation(p.modules.filter(o=>ids.has(o.id)&&!o.locked),result.module.x-old.x,result.module.z-old.z);for(const item of p.modules.filter(o=>ids.has(o.id)&&!o.locked)){item.x=Math.round(item.x+dx);item.z=Math.round(item.z+dz);}if(settings.block&&!canPlace(p,[...ids])){p.modules.forEach((item,i)=>Object.assign(item,before[i]));hud.textContent='Пересечение: перенос заблокирован';}else{hud.textContent=result.guides.join(' · ')||`X ${m.x} · Z ${m.z} мм`;for(const item of p.modules){const g=scene.groups.get(item.id);if(g)g.position.set(item.x/1000,item.y/1000,item.z/1000);}}hud.hidden=false;scene.dirty=true;};
const oldEnd=scene.onMoveEnd;scene.onMoveEnd=(...args)=>{oldEnd(...args);hud.hidden=true;};const oldResize=scene.onResize;scene.onResize=(id,axis,value,partId)=>{const m=getProject().modules.find(m=>m.id===id);if(!partId&&settings.coupled)resizeCoupled(m,axis,value);oldResize(id,axis,value,partId);hud.hidden=false;hud.textContent=`${{width:'Ширина',height:'Высота',depth:'Глубина'}[axis]}: ${Math.round(value)} мм`;};
const oldView=scene.setView.bind(scene);scene.setView=v=>{oldView(v);attach();};
function render(){const m=current();if(!m){ids.clear();gizmo.detach();return;}if(!ids.has(m.id)){ids.clear();ids.add(m.id);}if(!ids.size)ids.add(m.id);for(const id of [...ids])if(!getProject().modules.some(m=>m.id===id))ids.delete(id);$('#selection-info').textContent=`Выбрано: ${ids.size} · Shift/Ctrl + щелчок добавляет модуль`;$('#group-picker').innerHTML=getProject().modules.map(o=>`<label><input type="checkbox" data-multi="${esc(o.id)}" ${ids.has(o.id)?'checked':''}> ${esc(o.name)} ${o.groupId?'▣':''}</label>`).join('');const root=scene.groups.get(m.id);const rows=[];root?.traverse(o=>{if(o.isGroup&&o.userData.partId){let depth=0,parent=o.parent;while(parent&&parent!==root){if(parent.userData.partId)depth++;parent=parent.parent;}rows.push(`<button data-tree="${o.userData.partId}" style="padding-left:${10+depth*20}px">${depth?'↳ ':''}${esc(o.userData.label)}</button>`);}});$('#part-tree').innerHTML=rows.join('');$('#finish-class').value=m.finishClass||'matte';$('#edge-color').value=m.edgeColor||'#c5ac84';$('#front-gap').value=m.frontGap||4;attach();}
panel.onclick=async e=>{const b=e.target.closest('button');if(!b)return;const p=getProject(),m=current();if(b.dataset.gizmo){active=true;gizmoMode=b.dataset.gizmo;scene.mode='gizmo';for(const id of ['orbit-tool','move-tool','resize-tool'])$('#'+id).setAttribute('aria-pressed','false');$('#interaction-hint').textContent='Тяните оси XYZ или кольцо · точные координаты в свойствах';attach();toast('Тяните ось или кольцо. Точные координаты — в свойствах модуля.');}if(b.id==='gizmo-off'){active=false;gizmo.detach();gizmo.enabled=false;scene.mode='orbit';scene.controls.enabled=true;}if(b.dataset.tree)selectPart(b.dataset.tree);if(b.id==='group-selected'){if(ids.size<2){toast('Выберите хотя бы два модуля');return;}const groupId=crypto.randomUUID();p.modules.filter(m=>ids.has(m.id)&&!m.locked).forEach(m=>m.groupId=groupId);commit();}if(b.id==='ungroup-selected'){p.modules.filter(m=>ids.has(m.id)&&!m.locked).forEach(m=>m.groupId='');commit();}if(b.dataset.alignPro){const backup=structuredClone(p.modules);alignModules(p.modules,[...ids],b.dataset.alignPro);if(settings.block&&!canPlace(p,[...ids])){p.modules=backup;toast('Выравнивание вызвало пересечение');}commit({rebuild:true});}if(b.id==='construction-check'){const warnings=[...constructionWarnings(p,settings),...openingWarnings(p)];$('#construction-result').innerHTML='<p>Оценка геометрии; не расчёт прочности и не проверка артикула.</p>'+ (warnings.length?'<ul>'+warnings.map(w=>`<li>${esc(w.message)}</li>`).join('')+'</ul>':'<p>По выбранным пределам замечаний нет.</p>');}if(b.id==='quality-render')await quality();};
panel.onchange=e=>{const el=e.target,m=current();if(el.dataset.multi){el.checked?ids.add(el.dataset.multi):ids.delete(el.dataset.multi);scene.select(scene.selected);render();return;}if(el.id==='smart-snap')settings.snap=el.checked;if(el.id==='join-gap')settings.gap=Math.max(0,Math.min(100,+el.value));if(el.id==='block-overlap')settings.block=el.checked;if(el.id==='coupled-size')settings.coupled=el.checked;if(el.id==='shelf-limit')settings.maxShelf=Math.max(300,Math.min(2000,+el.value));if(el.id==='door-limit')settings.maxDoor=Math.max(300,Math.min(1500,+el.value));if(el.id==='finish-class'||el.id==='edge-color'||el.id==='front-gap'){if(!m||m.locked)return;const key={'finish-class':'finishClass','edge-color':'edgeColor','front-gap':'frontGap'}[el.id];m[key]=el.id==='front-gap'?Math.max(1,Math.min(12,+el.value)):el.value;scene.updateModule(m);commit();}};
async function quality(){const dialog=document.createElement('dialog');dialog.className='pro-dialog';dialog.innerHTML='<h2>Качественный снимок</h2><p>Повышенное разрешение и карта теней. Изображение включает текущий ракурс.</p><progress max="3" value="0"></progress><button id="render-cancel">Отмена</button>';document.body.append(dialog);dialog.showModal();let cancel=false;dialog.oncancel=()=>{cancel=true;};dialog.querySelector('button').onclick=()=>{cancel=true;};const r=scene.renderer,size=r.getSize(new THREE.Vector2()),pixel=r.getPixelRatio(),shadow=scene.sun.shadow.mapSize.clone(),ov=scene.overlay.visible,hv=helper.visible;try{await new Promise(resolve=>requestAnimationFrame(resolve));dialog.querySelector('progress').value=1;if(cancel)return;scene.overlay.visible=false;helper.visible=false;r.setPixelRatio(1);const factor=Math.min(2,3840/size.x,2160/size.y);r.setSize(Math.round(size.x*factor),Math.round(size.y*factor),false);scene.sun.shadow.mapSize.set(4096,4096);scene.sun.shadow.map?.dispose();scene.sun.shadow.map=null;dialog.querySelector('progress').value=2;await new Promise(resolve=>requestAnimationFrame(resolve));if(cancel)return;scene.renderFrame();const url=r.domElement.toDataURL('image/png');dialog.querySelector('progress').value=3;if(!cancel){downloadPNG(url,'Batesto — качественный снимок.png');toast('Снимок подготовлен для скачивания');}}catch(err){toast('Не удалось создать снимок: '+err.message);}finally{r.setPixelRatio(pixel);r.setSize(size.x,size.y);scene.sun.shadow.mapSize.copy(shadow);scene.sun.shadow.map?.dispose();scene.sun.shadow.map=null;scene.overlay.visible=ov;helper.visible=hv;scene.dirty=true;dialog.close();dialog.remove();}}
return {render,settings,detach(){active=false;gizmo.detach();gizmo.enabled=false;}};}
